package com.nexus.access.backend.place;
import java.util.*; import org.locationtech.jts.geom.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.nexus.access.backend.common.LocationDTO; import com.nexus.access.backend.exception.ResourceNotFoundException;
@Service @Transactional public class PlaceService { private static final GeometryFactory GEOMETRY_FACTORY=new GeometryFactory(new PrecisionModel(),4326); private final PlaceRepository repository; public PlaceService(PlaceRepository r){repository=r;} @Transactional(readOnly=true) public Page<PlaceResponseDTO> list(int page,int size,String sort){String property=Set.of("name","accessibilityScore","createdAt").contains(sort)?sort:"name";return repository.findAll(PageRequest.of(page,Math.min(size,100),Sort.by(property))).map(this::dto);} @Transactional(readOnly=true) public PlaceResponseDTO get(UUID id){return dto(find(id));} public PlaceResponseDTO create(CreatePlaceRequest r){Place p=new Place();apply(p,r.name(),r.description(),r.address(),r.city(),r.district(),r.placeType(),r.accessibilityScore(),r.location(),r.active());return dto(repository.save(p));} public PlaceResponseDTO update(UUID id,UpdatePlaceRequest r){Place p=find(id);apply(p,r.name(),r.description(),r.address(),r.city(),r.district(),r.placeType(),r.accessibilityScore(),r.location(),r.active());return dto(p);} public void delete(UUID id){repository.delete(find(id));} @Transactional(readOnly=true) public List<NearbyPlaceResponseDTO> nearby(double lat,double lon,double radius){return repository.findNearby(lat,lon,radius).stream().map(p->new NearbyPlaceResponseDTO(p.getId(),p.getName(),p.getAddress(),p.getAccessibilityScore(),p.getDistanceMeters(),new LocationDTO(p.getLatitude(),p.getLongitude()))).toList();} private Place find(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Place not found: "+id));} private void apply(Place p,String n,String d,String a,String c,String district,String type,int score,LocationDTO l,boolean active){p.setName(n);p.setDescription(d);p.setAddress(a);p.setCity(c);p.setDistrict(district);p.setPlaceType(type);p.setAccessibilityScore(score);p.setLocation(GEOMETRY_FACTORY.createPoint(new Coordinate(l.longitude(),l.latitude())));p.setActive(active);} private PlaceResponseDTO dto(Place p){Point point=p.getLocation();return new PlaceResponseDTO(p.getId(),p.getName(),p.getDescription(),p.getAddress(),p.getCity(),p.getDistrict(),p.getPlaceType(),p.getAccessibilityScore(),new LocationDTO(point.getY(),point.getX()),p.isActive(),p.getCreatedAt(),p.getUpdatedAt());}}
